import{_t as e,it as t,n,rt as r}from"./chunks/framework.CzJE1L4g.js";var i=JSON.parse(`{"title":"Reference: API quick tables","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/reference.md","filePath":"en/guide/reference.md"}`),a={name:`en/guide/reference.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="reference-api-quick-tables" tabindex="-1">Reference: API quick tables <a class="header-anchor" href="#reference-api-quick-tables" aria-label="Permalink to “Reference: API quick tables”">​</a></h1><p>One page of lookups: a class, one sentence, its key methods. For the semantics (where every injection point is, when a hook does not interfere), go to the files listed under <a href="#where-to-read-the-real-implementations">Where to read the real implementations</a>.</p><h2 id="coordinates-and-modules" tabindex="-1">Coordinates and modules <a class="header-anchor" href="#coordinates-and-modules" aria-label="Permalink to “Coordinates and modules”">​</a></h2><table tabindex="0"><thead><tr><th>Module / mod id</th><th>Coordinate</th><th>Contents</th></tr></thead><tbody><tr><td><code>fabric-api</code> (aggregate)</td><td><code>cn.enaium.fabricpvz:fabric-api:1.2.2</code></td><td>No code; depending on this coordinate brings the five modules, and the aggregate jar carries them <strong>inside itself</strong> (jar-in-jar), so an installation has one file</td></tr><tr><td><code>api-base</code></td><td>via the aggregate</td><td><code>PvzFabricApi</code>, <code>ModQuery</code>, the event bus (<code>api.event</code>)</td></tr><tr><td><code>api-events</code></td><td>via the aggregate</td><td><code>LawnEvents</code> (gameplay), <code>GameLifecycleEvents</code> (lifecycle) and the two bridges</td></tr><tr><td><code>api-plant</code></td><td>via the aggregate</td><td><code>PlantType</code>, <code>PlantRegistry</code>, <code>PlantOverrides</code>, <code>ProjectileOverrides</code>, <code>BoardOverrides</code>, <code>CustomPlantEvents</code>, <code>PlantRules</code>, <code>PlantHooks</code></td></tr><tr><td><code>api-resource</code></td><td>via the aggregate</td><td><code>ModImages</code>, <code>ModImageSlot</code>, <code>GameArt</code>, <code>ModReanims</code>, <code>ResourceOverrides</code>, <code>ResourceDiagnostics</code></td></tr><tr><td><code>api-zombie</code></td><td>via the aggregate</td><td><code>ZombieType</code>, <code>ZombieRegistry</code>, <code>ZombieOverrides</code>, <code>CustomZombieEvents</code>, <code>ZombieHooks</code></td></tr></tbody></table><p>The API is an <strong>optional dependency</strong>: when the sources use it, the mod declares <code>cn.enaium.fabricpvz:fabric-api:1.2.2</code> itself (<code>compileOnly</code> / <code>testCompileOnly</code> for compilation, <code>testImplementation</code> / <code>pvzRunClasspath</code> with <code>isTransitive = false</code> for runtime), and lists the module ids (or <code>&quot;fabric-api&quot;</code>) in its <code>fabric.mod.json</code>&#39;s <code>depends</code>. A mod that does not use the API declares no coordinate at all. The toolchain neither supplies the API nor picks its version.</p><h2 id="api-base" tabindex="-1"><code>api-base</code> <a class="header-anchor" href="#api-base" aria-label="Permalink to “api-base”">​</a></h2><table tabindex="0"><thead><tr><th>Class / method</th><th>Description</th></tr></thead><tbody><tr><td><code>PvzFabricApi.MOD_ID</code> / <code>.BASE_MOD_ID</code> / <code>.VERSION</code></td><td><code>&quot;fabric-api&quot;</code> / <code>&quot;api-base&quot;</code> / the API version</td></tr><tr><td><code>PvzFabricApi.isInitialized()</code> / <code>.getVersion()</code></td><td>Whether the API&#39;s own <code>main</code> entry point ran / its version</td></tr><tr><td><code>PvzFabricApi.getMods()</code> / <code>.getModContainer(id)</code> / <code>.getEntrypoints(key, type)</code></td><td>Wrappers around loader queries</td></tr><tr><td><code>ModQuery.isModLoaded(id)</code> / <code>.getModContainer(id)</code> / <code>.getModVersion(id)</code></td><td>Lightweight loader queries</td></tr><tr><td><code>Event&lt;T&gt;#register(listener)</code> / <code>#invoker()</code></td><td>Registration and the current invoker (Fabric&#39;s shape)</td></tr><tr><td><code>EventFactory.createArrayBacked(type, invokerFactory)</code></td><td>Creates an array-backed event; the only factory here</td></tr><tr><td><code>ListenerException</code></td><td>A failing listener&#39;s exception, wrapped with the event and listener context</td></tr></tbody></table><h2 id="api-events" tabindex="-1"><code>api-events</code> <a class="header-anchor" href="#api-events" aria-label="Permalink to “api-events”">​</a></h2><table tabindex="0"><thead><tr><th>Class / member</th><th>Description</th></tr></thead><tbody><tr><td><code>LawnEvents.LEVEL_START</code></td><td><code>(Board, int level, int gameMode, int background)</code>: level initialisation finished</td></tr><tr><td><code>LawnEvents.LEVEL_END</code></td><td><code>(Board, int result)</code>: the level ended (win/loss)</td></tr><tr><td><code>LawnEvents.WAVE_START</code></td><td><code>(Board, int waveIndex, int[] zombieTypes)</code>: a wave is about to spawn; <code>true</code> cancels it</td></tr><tr><td><code>LawnEvents.ZOMBIE_SPAWN</code></td><td><code>(Board, int zombieType, int row, boolean fromWave)</code>: <code>true</code> cancels the spawn</td></tr><tr><td><code>LawnEvents.ZOMBIE_DEATH</code> / <code>.ZOMBIE_DAMAGE</code></td><td>Death notification / damage value chain</td></tr><tr><td><code>LawnEvents.PLANT_PLACED</code> / <code>.PLANT_REMOVED</code> / <code>.PLANT_DAMAGE</code></td><td>Placement / removal (with a reason code) / damage value chain</td></tr><tr><td><code>LawnEvents.SUN_COLLECTED</code></td><td><code>(Board, int amount, int source)</code>: the amount actually credited</td></tr><tr><td><code>LawnEvents.PLANTING_VALIDATED</code></td><td><code>(Board, int x, int y, int seedType, int reason)</code>: return <code>PLANTING_OK</code> to force it through</td></tr><tr><td><code>LawnEvents.TICK</code></td><td><code>(Board, int tick)</code>: every tick (100 per second)</td></tr><tr><td><code>LawnEvents.PRE_DRAW</code> / <code>.POST_DRAW</code></td><td><code>(Board, Graphics)</code>: before / after the board&#39;s objects are drawn</td></tr><tr><td><code>GameLifecycleEvents.INITIALIZED</code></td><td>Once per process: start-up finished (assets loaded, main loop next)</td></tr><tr><td><code>GameLifecycleEvents.EXITING</code></td><td>Once per process: shutdown is beginning</td></tr><tr><td><code>LawnHooksBridge</code> / <code>AppHooksBridge</code></td><td>Wire the game&#39;s hook call sites to the event bus (installed by the module&#39;s entry point)</td></tr></tbody></table><h2 id="api-plant" tabindex="-1"><code>api-plant</code> <a class="header-anchor" href="#api-plant" aria-label="Permalink to “api-plant”">​</a></h2><table tabindex="0"><thead><tr><th>Class / method</th><th>Description</th></tr></thead><tbody><tr><td><code>PlantType.builder(String id)</code> → <code>Builder</code> → <code>register()</code></td><td>Registers a new plant; <code>register()</code> returns the <code>PlantType</code> and <code>seedType()</code> is the game&#39;s integer id</td></tr><tr><td>Every <code>Builder</code> field</td><td>See the table in <a href="./content.html">Plants and zombies</a>: <code>name</code> / <code>tooltip</code> / <code>almanacDescription</code> / <code>stringKeyStem</code> / <code>cost</code> / <code>refreshTime</code> / <code>reanimation</code> / <code>subClass</code> / <code>launchRate</code> / <code>health</code> / <code>projectile</code> / <code>burst</code> / <code>unlockAfter</code> / <code>packetArt…</code> / <code>aquatic</code> / <code>fungus</code> / <code>nocturnal</code> / <code>flying</code> / <code>upgrade</code> / <code>upgradeFrom</code> / <code>chooserVisible</code> / <code>onTick</code> / <code>onPlanted</code> / <code>plantRect</code> / <code>plantAttackRect</code> / <code>plantingRule</code></td></tr><tr><td><code>PlantType#id()</code> / <code>#seedType()</code> / <code>#definition()</code></td><td>Registration id / game id / the underlying <code>CustomPlantType</code></td></tr><tr><td><code>PlantRegistry.FIRST_SEED_TYPE</code></td><td>The first id handed to registered content (<code>100</code>)</td></tr><tr><td><code>PlantRegistry.get(int)</code> / <code>.get(String)</code> / <code>.all()</code> / <code>.count()</code></td><td>Querying registered plants</td></tr><tr><td><code>PlantRegistry.isCustomSeedType(int)</code></td><td>Whether an id is inside the range reserved for registered content</td></tr><tr><td><code>PlantRegistry.canPlantAt(board, x, y, seedType)</code></td><td>Whether the game would allow the placement (mod rules included)</td></tr><tr><td><code>PlantRegistry.place(board, x, y, seedType)</code></td><td>Place a plant without a seed packet</td></tr><tr><td><code>PlantRegistry.unregister(int)</code> / <code>.reset()</code></td><td>Unregister / clear (tests)</td></tr><tr><td><code>PlantOverrides.of(seedType)</code> → <code>PlantOverride</code></td><td>Overriding an existing (retail included) plant&#39;s numbers: <code>cost</code> / <code>refreshTime</code> / <code>launchRate</code> / <code>bodyHealth</code> / <code>spawnCountdown</code> / <code>biteInsteadOfEatZombieType</code> / <code>digestCountdown</code> / <code>spikeRockDamage</code> / <code>explosionBlast</code> / <code>producedCoins</code> / <code>crushProof</code></td></tr><tr><td><code>PlantOverrides.notOnGroundState(int)</code> / <code>.extraFireSeedType(int)</code></td><td>The two whole-game rules</td></tr><tr><td><code>PlantOverrides.registered()</code> / <code>.rules()</code> / <code>.reset()</code></td><td>Diagnostics and clearing</td></tr><tr><td><code>ProjectileOverrides.of(projectileType).damage(int)</code></td><td>Overriding projectile damage (one table write, no mixin)</td></tr><tr><td><code>BoardOverrides.allowZombies(gameMode, zombieTypes…)</code></td><td>Extra zombies a mode allows</td></tr><tr><td><code>BoardOverrides.allowZombieOnLevel(type, level, boolean)</code></td><td>Overrides one cell of the allowed table</td></tr><tr><td><code>BoardOverrides.relaxZombieSpawnRules(boolean)</code></td><td>Drops the starting-level and weight vetoes</td></tr><tr><td><code>BoardOverrides.beghouledWinningScore(int)</code> / <code>.killAllZombiesDamage(int)</code> / <code>.rainSeedInterval(int, int)</code> / <code>.stageHasGraveStones(boolean)</code></td><td>Per-mode level numbers</td></tr><tr><td><code>BoardOverrides.sunValues(int, int, int)</code> / <code>.sunMoneyCap(int)</code></td><td>Sun values (normal/small/large) / the bank cap</td></tr><tr><td><code>BoardOverrides.conveyorSeed(gameMode, from, to)</code> / <code>.sunSpawning(gameMode, coinType)</code> / <code>.skyDropCoin(coinType)</code></td><td>Conveyor seeds and sky drops</td></tr><tr><td><code>BoardOverrides.dropLootSunBranch(boolean)</code> / <code>.dropLootCoins(int, int, int)</code></td><td>The loot-sun branch and its three coins</td></tr><tr><td><code>BoardOverrides.lastStandInitialSun(int)</code> / <code>.coinUsableSeedType(int)</code></td><td>Last Stand&#39;s opening sun / a coin&#39;s default usable seed</td></tr><tr><td><code>BoardOverrides.numWaves(retailWaves, waves)</code> / <code>.seedNotAllowedToPick(gameMode, seedTypes…)</code> / <code>.graveBusterNeedsGravesInverted(boolean)</code></td><td>The wave table / chooser bans / the grave requirement bit</td></tr><tr><td><code>CustomPlantEvents.TICK</code> / <code>.PLACED</code></td><td>Observing <strong>registered</strong> plants globally</td></tr><tr><td><code>PlantHooks</code></td><td>The injection points themselves (used by the module, public for diagnostics and tests): <code>isUpgrade</code> / <code>isUpgradableTo</code> / <code>onPlanted</code> / <code>onTick</code> / <code>plantRect</code> / <code>drawPacketArt</code> / <code>fire</code> / <code>burstOf</code> …</td></tr><tr><td><code>PlantBehaviour</code> / <code>PlantingRule</code></td><td>The behaviour interfaces (the builder&#39;s callbacks are adapted into them)</td></tr></tbody></table><h2 id="api-zombie" tabindex="-1"><code>api-zombie</code> <a class="header-anchor" href="#api-zombie" aria-label="Permalink to “api-zombie”">​</a></h2><table tabindex="0"><thead><tr><th>Class / method</th><th>Description</th></tr></thead><tbody><tr><td><code>ZombieType.builder(String id)</code> → <code>Builder</code> → <code>register()</code></td><td>Registers a new zombie; <code>zombieType()</code> is the game&#39;s id</td></tr><tr><td>Every <code>Builder</code> field</td><td>See <a href="./content.html">Plants and zombies</a>: <code>name</code> / <code>almanacDescription</code> / <code>stringKeyStem</code> / <code>bodyReanimation</code> / <code>headReanimation</code> / <code>headTrack</code> / <code>headBodyTrack</code> / <code>headHiddenTrack</code> / <code>headHiddenLayer</code> / <code>headTransform</code> / <code>health</code> / <code>helm</code> / <code>shield</code> / <code>flyingHealth</code> / <code>collider</code> / <code>attackRect</code> / <code>scale</code> / <code>canGoInPool</code> / <code>wave</code> / <code>pickWeight</code> / <code>startingLevel</code> / <code>points</code> / <code>onTick</code> / <code>onSpawned</code></td></tr><tr><td><code>ZombieRegistry.FIRST_ZOMBIE_TYPE</code></td><td>The first id handed to registered content (<code>64</code>)</td></tr><tr><td><code>ZombieRegistry.get(int)</code> / <code>.get(String)</code> / <code>.all()</code> / <code>.count()</code> / <code>.isCustomZombieType(int)</code></td><td>Queries</td></tr><tr><td><code>ZombieRegistry.spawn(board, zombieType, row, fromWave)</code></td><td>Spawns one through the game&#39;s own path</td></tr><tr><td><code>ZombieRegistry.WAVE_UI</code></td><td>The &quot;not part of any wave&quot; spawn constant</td></tr><tr><td><code>ZombieOverrides.of(zombieType)</code> → <code>ZombieOverride</code></td><td>Overriding an existing zombie&#39;s spawn numbers: <code>bodyHealth</code> / <code>helm</code> / <code>shieldHealth</code> / <code>phaseCounter</code> / <code>spawnsAs</code> / <code>bodyAnimation</code> / <code>mindControlBodyHealth</code></td></tr><tr><td><code>ZombieOverrides.mindControlBoost(int, int, float)</code> / <code>.burnImmunity(int, int…)</code> / <code>.coldRemovalChilledCounter(int)</code> / <code>.shieldAlwaysAbsorbs(boolean)</code></td><td>The four whole-game rules</td></tr><tr><td><code>ZombieOverrides.registered()</code> / <code>.rules()</code> / <code>.reset()</code> / <code>.remapType(int)</code> / <code>.apply(Zombie)</code></td><td>Diagnostics and clearing / type remapping</td></tr><tr><td><code>CustomZombieEvents.TICK</code> / <code>.SPAWNED</code></td><td>Observing <strong>registered</strong> zombies globally</td></tr><tr><td><code>ZombieHooks</code> / <code>ZombieBehaviour</code></td><td>Injection points and the behaviour interface (diagnostics, tests)</td></tr></tbody></table><h2 id="api-resource" tabindex="-1"><code>api-resource</code> <a class="header-anchor" href="#api-resource" aria-label="Permalink to “api-resource”">​</a></h2><table tabindex="0"><thead><tr><th>Class / method</th><th>Description</th></tr></thead><tbody><tr><td><code>ModImages.load(Class, String path)</code></td><td>Read a PNG from your jar</td></tr><tr><td><code>ModImages.blank(w, h)</code> / <code>.painted(w, h, painter)</code></td><td>A blank canvas / a canvas with a painter</td></tr><tr><td><code>ModImages.remapHue(image, pivotDegrees, compression)</code></td><td>Per-pixel hue remapping keeping saturation, brightness and alpha</td></tr><tr><td><code>ModImageSlot.claim(modId, name)</code></td><td>Take an <code>ImageID</code> slot the game never draws</td></tr><tr><td><code>ModImageSlot#setImage(Image)</code> / <code>#image()</code> / <code>#bound()</code> / <code>#id()</code> / <code>#name()</code></td><td>Install the image / the current image / whether it is bound / the id / the name</td></tr><tr><td><code>ModImageSlot.reset()</code></td><td>Clear every slot (tests)</td></tr><tr><td><code>GameArt.packetArt(seedType)</code></td><td>Let the game draw that seed&#39;s packet art into a 50×70 image (<code>null</code> while it cannot)</td></tr><tr><td><code>GameArt.cachedPlantFrame(seedType)</code></td><td>The cached frame the game builds for the cursor preview and zen garden</td></tr><tr><td><code>GameArt.installCachedPlantFrame(seedType, frame)</code></td><td>Put <strong>your</strong> frame into the game&#39;s cache</td></tr><tr><td><code>ModReanims.overrideTrackArt(reanim, mapper)</code></td><td>Recolour <strong>every art-carrying</strong> track (idempotent)</td></tr><tr><td><code>ModReanims.overrideTrackArt(reanim, trackNames, mapper)</code></td><td>Recolour the named tracks only</td></tr><tr><td><code>ModReanims.giveSeparateHeadLayer(plant)</code></td><td>Supply the extra &quot;head&quot; reanimation (idempotent)</td></tr><tr><td><code>ResourceOverrides.addRoot(Path)</code> / <code>.addFile(pakPath, Path)</code> / <code>.addBytes(pakPath, byte[])</code></td><td>Register a loose-file override (a directory / a single file / raw bytes)</td></tr><tr><td><code>ResourceOverrides.overriddenNames()</code> / <code>.clear()</code> / <code>.installed()</code></td><td>Diagnostics / clearing / whether the mixin is installed</td></tr><tr><td><code>ResourceDiagnostics</code></td><td>The module&#39;s own bookkeeping (resource-group callbacks, reinstall counts…), used by tests</td></tr></tbody></table><h2 id="where-to-read-the-real-implementations" tabindex="-1">Where to read the real implementations <a class="header-anchor" href="#where-to-read-the-real-implementations" aria-label="Permalink to “Where to read the real implementations”">​</a></h2><p>What you want to confirm, and the file to open (paths relative to the workspace root):</p><table tabindex="0"><thead><tr><th>To confirm</th><th>Open</th></tr></thead><tbody><tr><td>Which table a registration writes, how ids are allocated</td><td><code>fabric-api/api-plant/src/main/java/cn/enaium/fabricpvz/api/plant/PlantRegistry.java</code>, <code>api-zombie/.../ZombieRegistry.java</code></td></tr><tr><td>Which game method every injection point targets</td><td><code>fabric-api/api-plant/src/main/java/cn/enaium/fabricpvz/api/plant/PlantHooks.java</code> (the javadoc names the game method and the upstream <code>file:line</code> for each), <code>api-zombie/.../ZombieHooks.java</code>, and both modules&#39; <code>mixin/</code> directories</td></tr><tr><td>When an override takes effect</td><td><code>api-plant/.../mixin/PlantOverridesMixin.java</code>, <code>api-zombie/.../mixin/ZombieOverridesMixin.java</code>, <code>api-plant/.../mixin/BoardWavesMixin.java</code></td></tr><tr><td>Which game call site fires an event</td><td><code>PvZ-Portable/src/main/java/cn/enaium/fabricpvz/portable/lawn/hooks/LawnHooks.java</code> and <code>sexy/hooks/AppHooks.java</code>, plus <code>fabric-api/api-events/.../LawnHooksBridge.java</code></td></tr><tr><td>How the game finds resources and what the pak key rules are</td><td><code>PvZ-Portable/src/main/java/cn/enaium/fabricpvz/portable/sexy/pak/PakInterface.java</code>, <code>.../pvzp/ResourceLocator.java</code></td></tr><tr><td>What the toolchain actually supplies</td><td><code>loom/README.md</code>, <code>loom/src/main/kotlin/cn/enaium/fabricpvz/loom/PvzModPlugin.kt</code>, <code>PvzDist.kt</code>, <code>JarInJar.kt</code></td></tr><tr><td>What a mod looks like as a template</td><td><code>pvz-example-mod/</code> (minimal: events plus three mixins), <code>pvz-content-mod/</code> (content, art and an end-to-end test), <code>pvz-mod-95-edition/</code> (Kotlin, rule overrides)</td></tr></tbody></table>`,18)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};